import SwiftUIimport FirebaseAuthimport FirebaseFirestore // Required to talk to the databasestruct SignupView: View {    @State private var name = "" // Added Name field    @State private var email = ""    @State private var password = ""    @State private var confirmPassword = ""    @State private var errorMessage = ""        var body: some View {        ZStack {            Color.orange.ignoresSafeArea()                        VStack(spacing: 20) {                Text("Create Account")                    .font(.system(size: 40, weight: .bold))                    .foregroundColor(.white)                    .padding(.bottom, 30)                                // New Name Input                TextField("Full Name", text: $name)                    .textFieldStyle(.roundedBorder)                    .padding(.horizontal, 30)                                TextField("University Email (.edu)", text: $email)                    .textFieldStyle(.roundedBorder)                    .autocapitalization(.none)                    .keyboardType(.emailAddress)                    .padding(.horizontal, 30)                                SecureField("Password", text: $password)                    .textFieldStyle(.roundedBorder)                    .padding(.horizontal, 30)                                SecureField("Confirm Password", text: $confirmPassword)                    .textFieldStyle(.roundedBorder)                    .padding(.horizontal, 30)                                if !errorMessage.isEmpty {                    Text(errorMessage)                        .foregroundColor(.white)                        .font(.subheadline)                        .bold()                }                                Button(action: registerUser) {                    Text("Sign Up")                        .font(.headline)                        .foregroundColor(.orange)                        .frame(maxWidth: .infinity)                        .padding()                        .background(Color.white)                        .cornerRadius(12)                }                .padding(.horizontal, 30)                .padding(.top, 10)            }        }        .tint(.white)    }        func registerUser() {        errorMessage = ""                // Local Validation        guard password == confirmPassword else {            errorMessage = "Passwords do not match."            return        }        guard !name.isEmpty else {            errorMessage = "Please enter your name."            return        }                // 1. Create the Secure Auth Account        Auth.auth().createUser(withEmail: email, password: password) { result, error in            if let error = error {                errorMessage = error.localizedDescription                return            }                        // If successful, grab the secure UID Google just generated            guard let uid = result?.user.uid else { return }                        // 2. Build the Firestore Profile Document            let db = Firestore.firestore()            let userData: [String: Any] = [                "uid": uid,                "email": email,                "displayName": name,                "university": "Washington University in St. Louis",                "rating": 5.0,                "completedOrders": 0,                "stripeAccountId": ""            ]                        // 3. Save it to the "users" collection            db.collection("users").document(uid).setData(userData) { error in                if let error = error {                    errorMessage = "Account created, but failed to save profile: \(error.localizedDescription)"                } else {                    print("Success! Auth + Database Profile created for \(name).")                    // TODO: Navigate the user to the GrubU Home Feed                }            }        }    }}#Preview {    SignupView()}